///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_Chk_form
 * @description Chk form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_Chk_form = async function () {
    const sbmOptions = {
        id: "tx_Chk_form",
        method: "post",
        action: "/stdcd/mfInvest.do?method=investModifyProcess",
        ref: "dma_ChkFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name checkRegData
 * @description check Reg Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkRegData = function () {
    const vl = dma_hiddenStore.get("regType");
    if (vl !== '') {
        const tObj = $('input[name=std_cd_apct_tp_cd][value="' + vl + '"]');
        if (tObj.length > 0) {
            $(tObj)[0].checked = true;
        }
    }
    const email = dma_hiddenStore.get("ipt_regEmail");
    if (email !== '') {
        const emails = email.split("@");
        if (emails.length > 0) {
            $c.util.getComponent('ipt_email01').setValue(emails[0]);
        }
        if (emails.length > 1) {
            $c.util.getComponent('ipt_email02').setValue(emails[1]);
        }
    }
    const tel = dma_hiddenStore.get("ipt_regTel");
    if (tel !== '') {
        const tels = tel.split("-");
        if (tels.length > 0) {
            $c.util.getComponent('ipt_ph01').setValue(tels[0]);
        }
        if (tels.length > 1) {
            $c.util.getComponent('ipt_ph02').setValue(tels[1]);
        }
        if (tels.length > 2) {
            $c.util.getComponent('ipt_ph03').setValue(tels[2]);
        }
    }
    const fax = dma_hiddenStore.get("ipt_regFax");
    if (fax !== '') {
        const faxs = fax.split("-");
        if (faxs.length > 0) {
            $c.util.getComponent('ipt_fax01').setValue(faxs[0]);
        }
        if (faxs.length > 1) {
            $c.util.getComponent('ipt_fax02').setValue(faxs[1]);
        }
        if (faxs.length > 2) {
            $c.util.getComponent('ipt_fax03').setValue(faxs[2]);
        }
    }
    const hpNo = $c.util.getComponent('ipt_encrypCellphoneNo').getValue();
    const hpNos = hpNo.split("-");
    if (hpNos.length > 0) {
        $c.util.getComponent('ipt_encrypCellphoneNo1').setValue(hpNos[0]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo2').setValue(hpNos[1]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo3').setValue(hpNos[2]);
    }
};

/**
 * @method
 * @name setComma
 * @description set Comma 처리
 * @returns {void}
 * @hidden N
 */
scwin.setComma = function () {
    $c.num.formatNumber($('#ipt_isuAmt')[0]);
    (($c.util.getComponent('txt_isuAmtMoney') && $c.util.getComponent('txt_isuAmtMoney').setValue) ? $c.util.getComponent('txt_isuAmtMoney').setValue($c.num.formatNumberKor(String(((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).getValue) ? ($('#ipt_isuAmt')[0]).getValue() : (((($('#ipt_isuAmt')[0]) && typeof ($('#ipt_isuAmt')[0]).val === 'function') ? ($('#ipt_isuAmt')[0]).val() : ((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).value !== undefined) ? ($('#ipt_isuAmt')[0]).value : ($('#ipt_isuAmt')[0]))))) == null ? '' : ((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).getValue) ? ($('#ipt_isuAmt')[0]).getValue() : (((($('#ipt_isuAmt')[0]) && typeof ($('#ipt_isuAmt')[0]).val === 'function') ? ($('#ipt_isuAmt')[0]).val() : ((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).value !== undefined) ? ($('#ipt_isuAmt')[0]).value : ($('#ipt_isuAmt')[0])))))).replace(/,/g, ''))) : console.warn('[sdd] num2won 대상 미해결: ' + 'isu_amt_money'));
};

/**
 * @method
 * @name setInsurInfo
 * @description set Insur Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.setInsurInfo = function () {
    if ($("td#std_cd_apct_tp_cd input:checked").val() === "1") {
        $c.util.getComponent('ipt_applComNm').setValue('' + dma_map.get("comNm") + '');
    } else {
        $c.util.getComponent('ipt_applComNm').setValue("");
    }
};

/**
 * @method
 * @name dataLenCheck
 * @description data Len Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataLenCheck = async function () {
    len = $c.str.getByteLength($c.util.getComponent('ipt_delRsn').getValue());
    if (len < 10) {
        await $c.win.alert("수정사유는 한글5자, 영문10자 이상 입력하세요.");
        $c.util.getComponent("ipt_delRsn").focus();
        return false;
    }
    if (len > 60) {
        await $c.win.alert("수정사유는 한글30자, 영문60자 이내로 입력하세요.");
        $c.util.getComponent("ipt_delRsn").focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name dataValidation
 * @description data Validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataValidation = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_jntBzNm').getValue()) === 0) {
        await $c.win.alert("공동사업명을 입력하세요.");
        $c.util.getComponent("ipt_jntBzNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_isuAmt').getValue()) === 0) {
        await $c.win.alert("발행금액을 입력하세요.");
        $c.util.getComponent("ipt_isuAmt").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_currTpCd').getValue()) === 0) {
        await $c.win.alert("발행통화를 선택하세요.");
        document.curr_tp_cd.focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_contrtStrtDd').getValue()) === 0) {
        await $c.win.alert("계약시작일을 입력하세요.");
        $c.util.getComponent("cal_contrtStrtDd").focus();
        return true;
    }
    const sys_today = (String(((dma_pageContext.get("sys_today") ?? "")) == null ? '' : ((dma_pageContext.get("sys_today") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("sys_today") ?? "")) == null ? '' : ((dma_pageContext.get("sys_today") ?? ""))));
    if ($c.str.getByteLength($c.util.getComponent('cal_contrtEndDd').getValue()) === 0) {
        await $c.win.alert("계약종료일을 입력하세요.");
        $c.util.getComponent("cal_contrtEndDd").focus();
